    const gpu = GPUS[q.gpu], m = MODELS[q.model];
    const usable = gpu.hbm * 0.9;                       // vLLM gpu_memory_utilization
    const kvTok = m.kv * (q.kvFp8 ? 0.5 : 1);           // bytes per cached token
    const wInf = m.Ntot * 1;                            // FP8 inference weights, 1 byte per parameter

    // ---- the workload ----
    const B = q.prompts * q.samples;                    // trajectories per step
    const Lg = q.turns * q.genPerTurn;                  // generated tokens per trajectory
    const Le = q.turns * q.envPerTurn;                  // tool/observation tokens per trajectory (prefilled)
    const Ltot = q.prompt + Lg + Le;                    // final context length
    const Cbar = q.prompt + (Lg + Le) / 2;              // average context while decoding

    // ---- trainer: every token of every trajectory goes through forward + backward ----
    const fwdTok = 2 * m.Nact + 2 * m.layers * Ltot * m.dAttn;   // weights + causal attention
    const trainTok = B * Ltot;
