    const trainGpuS = trainFlops / (gpu.bf16 * q.mfu);
    const trainMin = Math.ceil((16 * m.Ntot) / (gpu.hbm * 0.6));  // 16 B/param of sharded state must fit

    // ---- rollout replica: smallest power of two whose weights take at most a quarter of HBM ----
    const g = q.g || pow2AtLeast(wInf / (0.25 * usable));
