    const decTok = B * Lg;
    const decGpuS = decTok / decPerGpu;
    const preTok = B * (q.prompt + Le);                // with prefix caching only new tokens prefill
    const preFlopsTok = 2 * m.Nact + 4 * m.layers * Cbar * m.dAttn;
    const preGpuS = (preTok * preFlopsTok) / (gpu.fp8 * 0.4);
    const rollGpuS = decGpuS + preGpuS;
    const preTurn = ((q.prompt / q.turns + q.envPerTurn) * preFlopsTok) / (g * gpu.fp8 * 0.4);
    const trajTime = (ts) => q.turns * (q.genPerTurn * ts + q.tool + preTurn);

